/* STAGE 10 - expected values of the DAX measures, computed in SQL on rpt (guide 2.2 step 3).
   Run in FoodDistributionDB after 09-01. Compare each value with the same measure in Power BI
   (card or table filtered on the same Persian period). Accept when |difference| < 1. */
SET NOCOUNT ON;
DROP TABLE IF EXISTS #T;
CREATE TABLE #T (Seq int IDENTITY(1,1), Period nvarchar(40), Measure nvarchar(80), SQL_Value decimal(28,6));
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Sales Amount', (SELECT SUM(f.Total_Amount) FROM rpt.Fact_Invoice f JOIN rpt.Dim_Date d ON d.DateKey=f.InvoiceDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Invoice Count', (SELECT COUNT(*) FROM rpt.Fact_Invoice f JOIN rpt.Dim_Date d ON d.DateKey=f.InvoiceDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Discount Amount', (SELECT SUM(f.Discount_Amount) FROM rpt.Fact_Invoice f JOIN rpt.Dim_Date d ON d.DateKey=f.InvoiceDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Avg Invoice Value', (SELECT SUM(f.Total_Amount)/NULLIF(COUNT(*),0) FROM rpt.Fact_Invoice f JOIN rpt.Dim_Date d ON d.DateKey=f.InvoiceDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Product Sales Amount', (SELECT SUM(f.Final_Amount) FROM rpt.Fact_InvoiceLine f JOIN rpt.Dim_Date d ON d.DateKey=f.InvoiceDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Quantity Sold', (SELECT SUM(f.Quantity) FROM rpt.Fact_InvoiceLine f JOIN rpt.Dim_Date d ON d.DateKey=f.InvoiceDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Order Count', (SELECT COUNT(DISTINCT f.Sales_Order_ID) FROM rpt.Fact_SalesOrderLine f JOIN rpt.Dim_Date d ON d.DateKey=f.OrderDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Cancelled Order Count', (SELECT COUNT(DISTINCT f.Sales_Order_ID) FROM rpt.Fact_SalesOrderLine f JOIN rpt.Dim_Date d ON d.DateKey=f.OrderDateKey WHERE d.PersianYearMonthKey = 140507 AND f.Order_Status=N'Cancelled');
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Sales YTD', (SELECT SUM(f.Total_Amount) FROM rpt.Fact_Invoice f JOIN rpt.Dim_Date d ON d.DateKey=f.InvoiceDateKey WHERE d.PersianYear = 1405 AND d.PersianMonth <= 7);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Sales PY', (SELECT SUM(f.Total_Amount) FROM rpt.Fact_Invoice f JOIN rpt.Dim_Date d ON d.DateKey=f.InvoiceDateKey WHERE d.PersianYearMonthKey = 140407);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Buying Customers', (SELECT COUNT(DISTINCT f.Customer_Key) FROM rpt.Fact_Invoice f JOIN rpt.Dim_Date d ON d.DateKey=f.InvoiceDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'New Customers', (SELECT COUNT(*) FROM (SELECT f.Customer_Key, MIN(f.Invoice_Date) fd FROM rpt.Fact_Invoice f GROUP BY f.Customer_Key) x JOIN rpt.Dim_Date d ON d.[Date]=x.fd WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Repeat Customer %', (SELECT CAST(SUM(CASE WHEN n>=2 THEN 1 ELSE 0 END) AS decimal(18,6))/NULLIF(COUNT(*),0) FROM (SELECT f.Customer_Key, COUNT(*) n FROM rpt.Fact_Invoice f JOIN rpt.Dim_Date d ON d.DateKey=f.InvoiceDateKey WHERE d.PersianYearMonthKey = 140507 GROUP BY f.Customer_Key) x);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Collected Amount', (SELECT SUM(f.Amount) FROM rpt.Fact_Payment f JOIN rpt.Dim_Date d ON d.DateKey=f.PaymentDateKey WHERE d.PersianYearMonthKey = 140507 AND f.Payment_Status=N'Successful');
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Outstanding Amount', (SELECT SUM(f.Outstanding_Amount) FROM rpt.Fact_Invoice f JOIN rpt.Dim_Date d ON d.DateKey=f.InvoiceDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Overdue Amount', (SELECT SUM(f.Outstanding_Amount) FROM rpt.Fact_Invoice f JOIN rpt.Dim_Date d ON d.DateKey=f.InvoiceDateKey WHERE d.PersianYearMonthKey = 140507 AND f.Invoice_Status=N'Overdue');
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Return Requests', (SELECT COUNT(*) FROM rpt.Fact_Return f JOIN rpt.Dim_Date d ON d.DateKey=f.ReturnDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Refund Amount', (SELECT SUM(f.Refund_Amount) FROM rpt.Fact_Return f JOIN rpt.Dim_Date d ON d.DateKey=f.ReturnDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Target Amount', (SELECT SUM(f.Target_Value) FROM rpt.Fact_SalesTarget f JOIN rpt.Dim_Date d ON d.DateKey=f.PeriodEndDateKey WHERE d.PersianYearMonthKey = 140507 AND f.Target_Level=N'Region');
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Target Achievement %', (SELECT (SELECT SUM(f.Total_Amount) FROM rpt.Fact_Invoice f JOIN rpt.Dim_Date d ON d.DateKey=f.InvoiceDateKey WHERE d.PersianYearMonthKey = 140507) / NULLIF((SELECT SUM(f.Target_Value) FROM rpt.Fact_SalesTarget f JOIN rpt.Dim_Date d ON d.DateKey=f.PeriodEndDateKey WHERE d.PersianYearMonthKey = 140507 AND f.Target_Level=N'Region'),0));
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Forecast Amount', (SELECT SUM(f.Forecast_Amount) FROM rpt.Fact_SalesForecast f JOIN rpt.Dim_Date d ON d.DateKey=f.PeriodEndDateKey WHERE d.PersianYearMonthKey = 140507 AND f.Forecast_Version=(SELECT MAX(Forecast_Version) FROM rpt.Fact_SalesForecast));
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Commission Amount', (SELECT SUM(f.Commission_Amount) FROM rpt.Fact_Commission f JOIN rpt.Dim_Date d ON d.DateKey=f.PeriodEndDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Lead Count', (SELECT COUNT(*) FROM rpt.Fact_Lead f JOIN rpt.Dim_Date d ON d.DateKey=f.CreatedDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Converted Leads', (SELECT SUM(f.Is_Converted) FROM rpt.Fact_Lead f JOIN rpt.Dim_Date d ON d.DateKey=f.CreatedDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Opportunity Count', (SELECT COUNT(*) FROM rpt.Fact_Opportunity f JOIN rpt.Dim_Date d ON d.DateKey=f.OpportunityDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Win Rate %', (SELECT CAST(SUM(f.Is_Won) AS decimal(18,6))/NULLIF(SUM(f.Is_Closed),0) FROM rpt.Fact_Opportunity f JOIN rpt.Dim_Date d ON d.DateKey=f.OpportunityDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Contract Count', (SELECT COUNT(*) FROM rpt.Fact_Contract f JOIN rpt.Dim_Date d ON d.DateKey=f.StartDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Contract Amount', (SELECT SUM(f.Contract_Amount) FROM rpt.Fact_Contract f JOIN rpt.Dim_Date d ON d.DateKey=f.StartDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Complaint Count', (SELECT COUNT(*) FROM rpt.Fact_CustomerFeedback f JOIN rpt.Dim_Date d ON d.DateKey=f.FeedbackDateKey WHERE d.PersianYearMonthKey = 140507 AND f.Feedback_Type=N'Complaint');
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Avg Rating', (SELECT AVG(CAST(f.Rating AS decimal(18,6))) FROM rpt.Fact_CustomerFeedback f JOIN rpt.Dim_Date d ON d.DateKey=f.FeedbackDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Campaign Budget', (SELECT SUM(f.Total_Allocated_Amount) FROM rpt.Fact_CampaignBudget f JOIN rpt.Dim_Date d ON d.DateKey=f.ApprovalDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Campaign Spend', (SELECT SUM(f.Actual_Spent) FROM rpt.Fact_CampaignCost f JOIN rpt.Dim_Date d ON d.DateKey=f.CostDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Promotion Sales', (SELECT SUM(f.Total_Amount) FROM rpt.Fact_Invoice f JOIN rpt.Dim_Date d ON d.DateKey=f.InvoiceDateKey WHERE d.PersianYearMonthKey = 140507 AND f.Promotion_Key<>-1);
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Impressions', (SELECT SUM(f.Metric_Value) FROM rpt.Fact_CampaignResult f JOIN rpt.Dim_Date d ON d.DateKey=f.MeasurementDateKey WHERE d.PersianYearMonthKey = 140507 AND f.Metric_Name=N'Impressions');
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Attributed Revenue', (SELECT SUM(f.Metric_Value) FROM rpt.Fact_CampaignResult f JOIN rpt.Dim_Date d ON d.DateKey=f.MeasurementDateKey WHERE d.PersianYearMonthKey = 140507 AND f.Metric_Name=N'Attributed_Revenue');
INSERT #T (Period, Measure, SQL_Value) SELECT N'ماه ۱۴۰۵/۰۷ (مهر)', N'Brand Activity Cost', (SELECT SUM(f.Activity_Cost) FROM rpt.Fact_BrandActivity f JOIN rpt.Dim_Date d ON d.DateKey=f.StartDateKey WHERE d.PersianYearMonthKey = 140507);
INSERT #T (Period, Measure, SQL_Value) SELECT N'سال ۱۴۰۴', N'Sales Amount', (SELECT SUM(f.Total_Amount) FROM rpt.Fact_Invoice f JOIN rpt.Dim_Date d ON d.DateKey=f.InvoiceDateKey WHERE d.PersianYear = 1404);
