INSERT #T (Period, Measure, SQL_Value) SELECT N'سال ۱۴۰۴', N'Order Count', (SELECT COUNT(DISTINCT f.Sales_Order_ID) FROM rpt.Fact_SalesOrderLine f JOIN rpt.Dim_Date d ON d.DateKey=f.OrderDateKey WHERE d.PersianYear = 1404);
INSERT #T (Period, Measure, SQL_Value) SELECT N'سال ۱۴۰۴', N'Cancelled Order Count', (SELECT COUNT(DISTINCT f.Sales_Order_ID) FROM rpt.Fact_SalesOrderLine f JOIN rpt.Dim_Date d ON d.DateKey=f.OrderDateKey WHERE d.PersianYear = 1404 AND f.Order_Status=N'Cancelled');
INSERT #T (Period, Measure, SQL_Value) SELECT N'سال ۱۴۰۴', N'Sales YTD', (SELECT SUM(f.Total_Amount) FROM rpt.Fact_Invoice f JOIN rpt.Dim_Date d ON d.DateKey=f.InvoiceDateKey WHERE d.PersianYear = 1404);
