INSERT #T (Period, Measure, SQL_Value) SELECT N'سال ۱۴۰۴', N'New Customers', (SELECT COUNT(*) FROM (SELECT f.Customer_Key, MIN(f.Invoice_Date) fd FROM rpt.Fact_Invoice f GROUP BY f.Customer_Key) x JOIN rpt.Dim_Date d ON d.[Date]=x.fd WHERE d.PersianYear = 1404);
INSERT #T (Period, Measure, SQL_Value) SELECT N'سال ۱۴۰۴', N'Repeat Customer %', (SELECT CAST(SUM(CASE WHEN n>=2 THEN 1 ELSE 0 END) AS decimal(18,6))/NULLIF(COUNT(*),0) FROM (SELECT f.Customer_Key, COUNT(*) n FROM rpt.Fact_Invoice f JOIN rpt.Dim_Date d ON d.DateKey=f.InvoiceDateKey WHERE d.PersianYear = 1404 GROUP BY f.Customer_Key) x);
INSERT #T (Period, Measure, SQL_Value) SELECT N'سال ۱۴۰۴', N'Collected Amount', (SELECT SUM(f.Amount) FROM rpt.Fact_Payment f JOIN rpt.Dim_Date d ON d.DateKey=f.PaymentDateKey WHERE d.PersianYear = 1404 AND f.Payment_Status=N'Successful');
INSERT #T (Period, Measure, SQL_Value) SELECT N'سال ۱۴۰۴', N'Outstanding Amount', (SELECT SUM(f.Outstanding_Amount) FROM rpt.Fact_Invoice f JOIN rpt.Dim_Date d ON d.DateKey=f.InvoiceDateKey WHERE d.PersianYear = 1404);
