INSERT #T (Period, Measure, SQL_Value) SELECT N'سال ۱۴۰۴', N'Return Requests', (SELECT COUNT(*) FROM rpt.Fact_Return f JOIN rpt.Dim_Date d ON d.DateKey=f.ReturnDateKey WHERE d.PersianYear = 1404);
INSERT #T (Period, Measure, SQL_Value) SELECT N'سال ۱۴۰۴', N'Refund Amount', (SELECT SUM(f.Refund_Amount) FROM rpt.Fact_Return f JOIN rpt.Dim_Date d ON d.DateKey=f.ReturnDateKey WHERE d.PersianYear = 1404);
INSERT #T (Period, Measure, SQL_Value) SELECT N'سال ۱۴۰۴', N'Target Amount', (SELECT SUM(f.Target_Value) FROM rpt.Fact_SalesTarget f JOIN rpt.Dim_Date d ON d.DateKey=f.PeriodEndDateKey WHERE d.PersianYear = 1404 AND f.Target_Level=N'Region');
