INSERT #T (Period, Measure, SQL_Value) SELECT N'سال ۱۴۰۴', N'Forecast Amount', (SELECT SUM(f.Forecast_Amount) FROM rpt.Fact_SalesForecast f JOIN rpt.Dim_Date d ON d.DateKey=f.PeriodEndDateKey WHERE d.PersianYear = 1404 AND f.Forecast_Version=(SELECT MAX(Forecast_Version) FROM rpt.Fact_SalesForecast));
INSERT #T (Period, Measure, SQL_Value) SELECT N'سال ۱۴۰۴', N'Commission Amount', (SELECT SUM(f.Commission_Amount) FROM rpt.Fact_Commission f JOIN rpt.Dim_Date d ON d.DateKey=f.PeriodEndDateKey WHERE d.PersianYear = 1404);
