INSERT #T (Period, Measure, SQL_Value) SELECT N'سال ۱۴۰۴', N'Complaint Count', (SELECT COUNT(*) FROM rpt.Fact_CustomerFeedback f JOIN rpt.Dim_Date d ON d.DateKey=f.FeedbackDateKey WHERE d.PersianYear = 1404 AND f.Feedback_Type=N'Complaint');
