INSERT #T (Period, Measure, SQL_Value) SELECT N'سال ۱۴۰۴', N'Campaign Budget', (SELECT SUM(f.Total_Allocated_Amount) FROM rpt.Fact_CampaignBudget f JOIN rpt.Dim_Date d ON d.DateKey=f.ApprovalDateKey WHERE d.PersianYear = 1404);
